import {LESSONS} from './lessons.js?v=122';
import {MISSIONS} from './mission.js?v=122';
const esc=x=>String(x||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function category(id,l){return /fireteam/.test(id)?'火力组':/FAQ/.test(l.kind+' '+l.title)?'FAQ':/cautious|climb|jump|Jump|narrow|height|lowwall|room|terrain/.test(id)?'移动与地形':/saves|removal|em$|para|doctor|engineer|guts/.test(id)?'过保与状态':/hacking|whiteNoise|possession|controlledJump|evoSupport|cybermine/.test(id)?'黑客与装备':'射击与反应';}
export function installLobby({startMatch,startLesson,resume,home,onRoute}){const root=document.getElementById('lobby');let page='home',filter='全部',search='';const saved=mode=>{try{return JSON.parse(localStorage.getItem('infi-sim-'+mode)||'null');}catch{return null;}};function draw(){document.body.classList.add('in-lobby');root.hidden=false;root.innerHTML=`<div class="lobby-shell"><div class="lobby-top"><a href="#home" id="lobbyBrand">⌁ infi<span>-sim</span></a><span>N5.3 · ITS18 · 非官方沙盘</span></div>${page==='home'?`<div class="lobby-hero"><div class="eyebrow">PLAN. DECLARE. RESOLVE.</div><h1>每一次宣告，<br><span>都是战术的开始。</span></h1><p>选择一场完整比赛，或用固定场景理解一条规则。</p></div><div class="entry-grid"><button class="entry-card match-entry" id="openMatch"><span class="entry-number">01 / MATCH</span><div class="entry-glyph">⌖</div><h2>真实比赛</h2><p>从任务选择到最后一次结算。</p><span class="entry-tags">ITS 任务 / 双方军表 / 部署 / 火力组</span><strong>配置一场比赛 <span>↗</span></strong></button><button class="entry-card tutorial-entry" id="openTutorials"><span class="entry-number">02 / FIELD ACADEMY</span><div class="entry-glyph">◇</div><h2>教学演示</h2><p>固定敌我配置，逐步验证规则与 FAQ。</p><span class="entry-tags">行动顺序 / 拼骰过保 / 技能 / FAQ</span><strong>选择教学场景 <span>↗</span></strong></button></div><div class="lobby-resume">${['match','tutorial'].filter(m=>saved(m)?.units?.length).map(m=>`<button data-resume="${m}">继续上次${m==='match'?'比赛':'教学'} →</button>`).join('')}</div>`:page==='match'?`<button class="lobby-back" id="lobbyBack">← 返回入口</button><div class="lobby-section-heading"><small>01 / MATCH SETUP</small><h1>配置真实比赛</h1><p>选择任务后，依序导入双方军表、掷先手权、部署并配置火力组。</p></div><div class="mission-options">${Object.entries(MISSIONS).map(([id,m],i)=>`<label class="mission-option"><input type="radio" name="mission" value="${id}" ${i?'':'checked'}><span><b>${esc(m.name)}</b><small>${esc(m.en)} · ITS18</small><p>${esc(m.description)}</p></span></label>`).join('')}</div><div class="setup-footer"><p>48″ × 48″ · 300 点级 · 12″部署区 · 3 轮<br>双方使用各自导入的精确配置；主动轮与 ARO 按规则处理。</p><button id="startMatch" class="primary">确认任务 → 导入双方军表</button></div>`:`<button class="lobby-back" id="lobbyBack">← 返回入口</button><div class="lobby-section-heading"><small>02 / FIELD ACADEMY</small><h1>一条规则，一个场景。</h1><p>每例固定双方单位、装备和起始位置，无需导入军表。默认随机掷骰，可在场景中开启标明点数的固定骰例。</p><p><a href="faq.html" target="_blank" rel="noopener noreferrer">FAQ 0.1：九项规则算例核对 ↗</a></p></div><div class="lesson-search"><label>查找教学<input id="lobbySearch" type="search" placeholder="搜索 FAQ、闪避、火力组…" value="${esc(search)}"></label></div><div class="lesson-filters">${['全部','FAQ','射击与反应','移动与地形','过保与状态','黑客与装备','火力组'].map(c=>`<button data-category="${c}" class="${c===filter?'active':''}">${c}</button>`).join('')}</div><div id="lobbyLessons" class="lesson-cards"></div>`}${page==='home'?`<section class="official-intro" aria-labelledby="officialIntroTitle"><div class="official-intro-heading"><span class="eyebrow">DISCOVER INFINITY</span><span class="community-label">非盈利 · 非官方工具</span></div><h2 id="officialIntroTitle">认识 Infinity</h2><p>Infinity 是 Corvus Belli 出品的科幻微缩模型战棋。玩家指挥特种小队，在立体地形中完成任务；命令分配与自动反应（ARO）让双方在每次行动中作出战术选择。</p><nav class="official-links" aria-label="Infinity 官方资源"><a href="https://infinityuniverse.com/en" target="_blank" rel="noopener noreferrer">Infinity 官方网站 ↗</a><a href="https://infinitythewiki.com/" target="_blank" rel="noopener noreferrer">官方规则 Wiki ↗</a><a href="https://infinityuniverse.com/army/" target="_blank" rel="noopener noreferrer">官方 Army 军表工具 ↗</a></nav><div class="community-note"><strong>关于 infi-sim</strong><p>本项目为非盈利、非官方的爱好者工具，仅用于规则测试、教学演示与 Infinity 推广，与 Corvus Belli 无隶属关系，亦非官方授权产品。游戏名称、商标、图标及相关资料的权利归 Corvus Belli 及各自权利人所有。本工具不能替代官方规则、FAQ 或赛事裁定。</p></div></section>`:''}<footer class="lobby-footer">INFI-SIM / 二维战术模拟器 <span>规则争议以最新官方规则及赛事裁定为准</span></footer></div>`;
const bind=(id,fn)=>{const e=document.getElementById(id);if(e)e.onclick=fn;};bind('lobbyBrand',()=>show('home'));bind('openMatch',()=>show('match'));bind('openTutorials',()=>show('tutorial'));bind('lobbyBack',()=>show('home'));root.querySelectorAll('[data-resume]').forEach(b=>b.onclick=()=>{resume(saved(b.dataset.resume));enter();});bind('startMatch',()=>{startMatch(root.querySelector('input[name="mission"]:checked').value);enter();});root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{filter=b.dataset.category;draw();});if(page==='tutorial'){const input=document.getElementById('lobbySearch');input.oninput=()=>{search=input.value;drawLessons();};drawLessons();}}
function drawLessons(){const choices=Object.entries(LESSONS).filter(([id,l])=>(filter==='全部'||category(id,l)===filter)&&(!search||[l.title,l.question,l.kind].join(' ').toLowerCase().includes(search.toLowerCase())));document.getElementById('lobbyLessons').innerHTML=choices.map(([id,l])=>`<button class="lesson-card" data-lesson="${id}"><small>${esc(category(id,l))}</small><h3>${esc(l.title)}</h3><p>${esc(l.question)}</p><span>固定场景 · 开始演示 ↗</span></button>`).join('')||'<p class="empty-lessons">没有找到匹配场景，试试其他关键词。</p>';root.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=async()=>{b.disabled=true;await startLesson(b.dataset.lesson);enter();});}
function show(p='home'){page=p;onRoute?.(p);draw();window.scrollTo(0,0);}function enter(){document.body.classList.remove('in-lobby');root.hidden=true;onRoute?.('play');window.scrollTo(0,0);}document.getElementById('homeBtn').onclick=()=>{home();show('home');};document.getElementById('tutorialCatalogBtn').onclick=()=>show('tutorial');return {show,enter};}
